CREATE TABLE IF NOT EXISTS university_catalog (id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE);
INSERT OR IGNORE INTO university_catalog(id,slug) VALUES ('atlas','istanbul-atlas-university'),('medipol','medipol-university'),('kent','istanbul-kent-university'),('beykoz','beykoz-university'),('fenerbahce','fenerbahce-university'),('topkapi','istanbul-topkapi-university');
CREATE TABLE IF NOT EXISTS student_accounts (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS student_sessions (token_hash TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES student_accounts(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_sessions (token_hash TEXT PRIMARY KEY,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS saved_items (student_id TEXT NOT NULL REFERENCES student_accounts(id),kind TEXT NOT NULL,item_id TEXT NOT NULL,content TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,PRIMARY KEY(student_id,kind,item_id));
CREATE TABLE IF NOT EXISTS student_journeys (id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES student_accounts(id),university_id TEXT NOT NULL REFERENCES university_catalog(id),program_id TEXT NOT NULL,content TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(student_id,university_id,program_id));
CREATE TABLE IF NOT EXISTS student_reviews (id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES student_accounts(id),university_id TEXT NOT NULL REFERENCES university_catalog(id),status TEXT NOT NULL DEFAULT 'verification_pending',content TEXT NOT NULL,evidence TEXT NOT NULL DEFAULT '[]',verification_method TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(student_id,university_id));
CREATE INDEX IF NOT EXISTS review_university_status ON student_reviews(university_id,status,created_at);
CREATE TABLE IF NOT EXISTS student_stories (id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES student_accounts(id),university_id TEXT NOT NULL REFERENCES university_catalog(id),status TEXT NOT NULL DEFAULT 'pending',content TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS student_ambassadors (student_id TEXT NOT NULL REFERENCES student_accounts(id),university_id TEXT NOT NULL REFERENCES university_catalog(id),opted_in INTEGER NOT NULL DEFAULT 0,blocked INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,PRIMARY KEY(student_id,university_id));
CREATE TABLE IF NOT EXISTS ambassador_questions (id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES student_accounts(id),university_id TEXT NOT NULL REFERENCES university_catalog(id),ambassador_id TEXT REFERENCES student_accounts(id),question TEXT NOT NULL,answer TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS platform_content (id TEXT PRIMARY KEY,kind TEXT NOT NULL,university_id TEXT REFERENCES university_catalog(id),content TEXT NOT NULL,published INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS travel_requests (id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES student_accounts(id),university_id TEXT REFERENCES university_catalog(id),kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested',content TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_audit (id TEXT PRIMARY KEY,action TEXT NOT NULL,entity_id TEXT NOT NULL,details TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS platform_rate_limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS platform_reports (id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES student_accounts(id),kind TEXT NOT NULL,item_id TEXT NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS platform_events (id TEXT PRIMARY KEY,event TEXT NOT NULL,university_id TEXT REFERENCES university_catalog(id),created_at INTEGER NOT NULL);
